INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-173123300', 'rightmove', '173123300', 'https://www.rightmove.co.uk/properties/173123300', 1150000, 'guide_price', 5, 3, 'semi_detached', 'Cuckmans Drive, St. Albans, AL2', 'AL2 3AX', 51.730855, -0.361608, 'freehold', NULL, NULL, NULL, 'E', NULL, NULL, NULL, '["Five generous bedrooms", "Two en-suite shower rooms", "Arranged over three floors", "Stunning kitchen/family/dining area", "Separate reception room", "Laundry room", "Large private garden", "Beautifully presented throughout", "Driveway parking"]', 'Beautifully presented and thoughtfully designed, this substantial five-bedroom semi-detached home offers versatile living space perfectly suited to modern family life. Arranged over three floors, the property combines generous proportions with a practical layout, creating a home that is as functional as it is stylish.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-173172728', 'rightmove', '173172728', 'https://www.rightmove.co.uk/properties/173172728', 800000, 'offers_over', 3, 2, 'flat', 'Sussex Way, London, N7', 'N7 6RR', 51.561682, -0.118237, 'leasehold', NULL, NULL, NULL, NULL, NULL, NULL, 'ground', '[]', 'Situated on the well-connected Sussex Way in North London, this well-proportioned three-bedroom flat offers a practical layout, generous living space, and the added benefit of a private garden. Arranged across two levels and extending to approximately 800 sq ft (74.2 sq m) of internal space, the property provides an ideal opportunity for families, first-time buyers, or investors seeking a home in a vibrant and convenient location. Upper Holloway Overground Station is just a short walk away, while Finsbury Park Station – offering Piccadilly and Victoria line services – is also within easy reach, making commuting into Central London fast and convenient. Several major bus routes stop just moments from your door, linking you directly to London Bridge, Waterloo, Trafalgar Square and more.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-173691080', 'rightmove', '173691080', 'https://www.rightmove.co.uk/properties/173691080', 550000, 'offers_over', 1, 1, 'flat', 'Almeida Street, Islington, N1', 'N1 1TB', 51.539663, -0.104193, 'share_of_freehold', 982, 700, NULL, 'E', NULL, NULL, NULL, '["1 double bedroom garden flat", "Sole use of private garden", "Barnsbury Conservation area", "Own private entrance", "Superb access to both Angel and Highbury & Islington stations"]', 'A stunning 1 double bedroom garden flat set within this phenomenally central location, right in the heart of Islington, within the Barnsbury conservation area, moments form the vibrant amenities of Upper Street, yet retaining peace and tranquillity on this cul-de-sac section of the road. The property is accessed via its own private entrance , opening in to the beautiful, spacious reception room with the focal point of the room being a stunning decorative fireplace. The kitchen is modern, well-appointed and finished to a high specification. The shower room is beautifully designed with a stunning walk-in shower, WC, hand basin and a window. To the rear is a beautiful private tiered patio garden, backing on to the gardens of the houses on Napier Grove. Almeida Street is a no through road off Upper Street, home to the renowned Almeida Theatre. The property affords superb access to the transport at Angel Underground (Northern Line) and Highbury & Islington Station (National Rail & Victoria Line) providing excellent links around London. The buzz of Upper Street is only a short walk away. The celebrated gastropubs the The Pig & Butcher, the Albion and the Drapers Arms can be found locally within Barnsbury. Supermarkets Waitrose and Sainsbury''s are located at the Southern end of Liverpool Road, close to Angel.
