INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-87710814', 'rightmove', '87710814', 'https://www.rightmove.co.uk/properties/87710814', 800000, NULL, 3, 2, 'flat', 'Leswin Road, Stoke Newington, London, N16', 'N16 7NX', 51.55993, -0.07326, 'leasehold', 115, 2589, 900, 'E', NULL, NULL, '1st', '["Gorgeous 3 bedroom flat on the 1st floor", "Located in a converted school house", "Bright reception room with ample space to relax", "Modern kitchen with dining space and fitted appliances", "3 sizeable bedrooms with floods of natural light", "Sleek shower room and additional en suite bathroom in the main bedroom", "Lovely terrace", "Located in the heart of Stoke Newington for amenities and transport links"]', 'Situated on the first floor of this attractive converted school, this stunning 3 bedroom flat boasts bright interiors and spacious rooms. It further benefits from a lovely private terrace.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-87758679', 'rightmove', '87758679', 'https://www.rightmove.co.uk/properties/87758679', 420000, NULL, 1, 1, 'flat', 'Empire Wharf, Victoria Park, E3', 'E3 5NQ', 51.534835, -0.034933, 'leasehold', 93, 2085.88, 200, 'D', NULL, NULL, 'fourth', '["Chain Free", "Gated Parking", "Canal and Park Views", "Good Transport Links", "Close to Victoria Park & Olympic Park", "Perfect Starter Home"]', 'WJ Meade are pleased to present this one bedroom apartment on the fourth floor of a secure gated private development next to Victoria Park. Arranged over 503 sq ft with a separate fitted kitchen to reception room with adjoining balcony with stunning views over the Hertford Union Canal. Perfectly situated for the vibrant amenities of Roman Road whilst being just moments from Victoria Park and the Olympic Park.', 'W J Meade, Mile End & Bow', '2026-03-31T19:53:43Z', '2026-10-23T23:02:38Z', '["floor_level"]');
