INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-87975228', 'rightmove', '87975228', 'https://www.rightmove.co.uk/properties/87975228', 800000, NULL, 2, 2, 'flat', 'Wandsworth Road, SW8, Nine Elms, London, SW8', 'SW8 2FA', 51.48142, -0.12827, 'leasehold', NULL, 0, 0, NULL, NULL, NULL, '7th', '["Stunning 2-bedroom apartment located in Nine Elms", "Bright, spacious rooms", "Sleek open-plan kitchen", "Communal gym", "Underground parking included", "Separate storage unit accessible on 2nd floor", "Local green space includes Vauxhall Park", "Nearby transport links consist of Nine Elms and Vauxhall Underground Stations"]', 'This stunning 2-bedroom apartment located in Nine Elms is situated on the 7th floor and features bright, spacious rooms, a sleek open-plan kitchen, a communal gym, and a private dining and lounge area for residents.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-88008885', 'rightmove', '88008885', 'https://www.rightmove.co.uk/properties/88008885', 1075000, 'fixed_price', 4, 2, 'terraced', 'Curzon Road, Ealing', 'W5 1NE', 51.526732, -0.317066, 'freehold', NULL, NULL, NULL, 'F', NULL, NULL, NULL, '["Impressive Edwardian Family Home", "Four Bedrooms & Two Bathrooms", "Impressive Kitchen/Family Room", "Ground Floor Guest wc", "No Onward Chain", "Lovely 51ft Deep Suntrap Garden", "Easy Access for Elizabeth Line Stations", "Off Street Parking", "North Ealing School Catchment Area", "Moments from Pitshanger Park"]', 'A beautifully presented and fully extended four-bedroom Edwardian home, featuring off-street parking and a delightful suntrap rear garden. The ground floor showcases an impressive, light-filled kitchen/family room, complete with a central island and bi-fold doors opening directly onto the garden, perfect for modern living and entertaining. To the front, there is a separate reception room with ample built-in storage, an attractive fireplace, and a bay window. Both the kitchen/family room and reception room benefit from underfloor heating. A convenient guest WC completes the ground floor. Upstairs, the first floor offers two generous double bedrooms, a further single bedroom, and a luxurious family bathroom. The second floor (loft conversion) hosts a spacious principal bedroom with ample storage and a modern shower room. Outside, the charming 51ft west-facing rear garden enjoys a sunny aspect and features a paved patio, lawn, and garden shed, ideal for outdoor dining and relaxation. As the vendor’s sole agent, we are delighted to confirm that the property is being sold with no onward chain, offering a straightforward and potentially swift transaction.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-88135962', 'rightmove', '88135962', 'https://www.rightmove.co.uk/properties/88135962', 550000, 'offers_over', 3, 1, 'terraced', 'Westward Road, Chingford', 'E4 8LZ', 51.610588, -0.019726, 'freehold', NULL, NULL, NULL, 'D', NULL, NULL, NULL, '["Three Bedroom House", "Mid Terrace", "Approx. 987 Square Foot", "Easy Access to Highams Park and Walthamstow", "Quiet Residential Location", "Potential To Extend (STPP)", "Circa 82 Foot South Facing Garden"]', 'This three-bedroom mid-terrace home offers approximately 987 square feet of thoughtfully arranged living space in a peaceful and well-established residential area. Positioned for easy access to both Highams Park and Walthamstow, the location combines a sense of calm with strong transport connections and local amenities. The property benefits from a generous 82-foot south-facing garden—ideal for relaxing, entertaining, or future landscaping plans. With clear scope to extend, subject to planning permission, there’s exciting potential here to grow and adapt the space to suit your needs. A solid opportunity in a quiet neighbourhood with excellent links and room to evolve.
