INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-89596509', 'rapidapi_uk_real_estate_rightmove', '89596509', 'https://www.rightmove.co.uk/properties/89596509', 1195000, 'guide_price', 4, 4, 'semi_detached', 'Woking Road, Jacob''s Well', 'GU4 7GD', 51.26476, -0.573237, 'freehold', NULL, NULL, NULL, 'F', NULL, NULL, 'ground', '["2532 sq ft", "4 bedroom suites", "2 reception rooms", "kitchen/family/dining room", "utility room", "parking spaces", "lovely sunny garden", "gated mews development"]', '3 White House Mews is an attractive attached family house with surprisingly spacious accommodation of 2,532 sq ft, arranged over three floors, set within a private gated mews of only three houses. Completed in 2020, the house has been built to an exacting standard in the Regency style at the rear, complimenting the original house that stood on the site for many years. There are four bedrooms, arranged over two floors, each with an en suite, and on the ground floor there are two reception rooms and a fine kitchen/dining room, with two sets of double doors leading out to an entertaining terrace and the sunny south backing garden. There is also a utility room and a cloakroom on this floor. Outside there is parking for three/four cars and a sunny rear garden.', 'Hill Clements, Guildford', '2026-06-11T15:08:39Z', '2026-10-23T23:15:42Z', '["floor_level"]');
