INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-91724019', 'rightmove', '91724019', 'https://www.rightmove.co.uk/properties/91724019', 875000, 'fixed_price', 3, 1, 'semi_detached', 'Meadvale Road, Ealing', 'W5 1LU', 51.527779, -0.315231, 'freehold', NULL, NULL, NULL, 'F', 'D', NULL, NULL, '["Semi Detached Period House", "Three Double Bedrooms", "Off Street Parking", "Southerly Aspect Rear Garden", "Two Reception Rooms", "No Onward Chain", "North Ealing School Catchment", "Scope for Rear Extension", "Council Tax Band - F/ EPC - D", "1165sqft (108.1sqm)"]', 'This semi-detached period home exudes charm with off-street parking and a delightful sunlit southerly-facing rear garden. Entering the ground floor reveals impressive entertaining space, featuring interconnected reception rooms and an eat-in kitchen. Ascending to the first floor, three generously-sized double bedrooms and a tastefully designed family bathroom await. Original fireplaces, picture rails, and ceiling details preserve the home''s character. Plus, with potential for expansion into the side return, subject to customary permissions, the possibilities for this property are as promising as its current allure. Enjoy the perfect blend of period elegance and modern living in this inviting abode.
