INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-93473145', 'rightmove', '93473145', 'https://www.rightmove.co.uk/properties/93473145', 500000, 'offers_over', 2, 1, 'flat', 'Island Apartments, 34 Coleman Fields, N1', 'N1 7BY', 51.538095, -0.094006, 'share_of_freehold', 229, 4000, NULL, 'D', NULL, NULL, 'fourth', '["2 double bedrooms", "Copious amounts of storage", "Modern open-plan living", "Close to transport links"]', 'A bright and spacious 2 double bedroom apartment located on the fourth floor of popular secure modern development, moments from the amenities of Essex Road and Upper Street. The property is well-proportioned comprising; two double bedrooms both with fitted wardrobes; contemporary bathroom with rainfall shower; stunning semi-open plan kitchen/living/dining space flooded with light from the dual aspect floor to ceiling windows. Island Apartments occupies a prominent position on the corner of Coleman Fields and Prebend Street, affording superb access to the walks of the canal and the greenery of the gardens of Rosemary Gardens and Shoreditch Park. Convenience shopping can be found at the Co-Operative & Tescos on New North Road along with Budgens on the corner of Packington Street and Prebend Street. The bars/pubs and deli''s of De Beauvoir are only a short stroll away on Southgate Road. Essex Road station provides good train links to the City, along with the Underground at both Highbury & Islington and Angel.
