INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-93565308', 'rightmove', '93565308', 'https://www.rightmove.co.uk/properties/93565308', 325000, NULL, 2, 2, 'flat', 'Abbotsmead Place, Caversham', 'RG4 8BB', 51.466815, -0.975238, 'leasehold', 96, 2556, 100, 'D', 'C', NULL, NULL, '["Central Caversham location", "Ground floor accommodation", "Two bedrooms", "En-suite to bedroom 1", "No onward chain", "Council tax band D", "EPC rating C"]', 'A spacious and well-planned apartment in a highly desirable location, within a stone''s throw of Caversham centre. The property is located the ground floor with French style doors leading out to communal garden. Th accommodation comprises - entrance hall, sitting room/dining room, kitchen, two double bedrooms, en-suite to bedroom one and a separate family bathroom. Further benefits include, secure entry phone system, allocated parking and communal ground.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-93609645', 'rapidapi_uk_real_estate_rightmove', '93609645', 'https://www.rightmove.co.uk/properties/93609645', 950000, 'guide_price', 4, 3, 'semi_detached', 'Riverside, Millbrook, Guildford, Surrey GU1', 'GU1 3XD', 51.2318, -0.572462, 'share_of_freehold', NULL, 4900.0, 0.0, 'G', NULL, NULL, 'ground', '["4 bedrooms", "1 - 2 reception rooms", "3 bathrooms", "Outdoor Home Office", "Garden", "Patio", "Semi-Detached"]', '4 Riverside is approached via its own private gated entrance from the car park, providing an added sense of security and privacy rarely found in such a central location. As you approach the front door, newly installed panelling with integrated LED lighting creates an inviting and contemporary arrival, immediately setting the tone for the stylish interior beyond.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-93639996', 'rightmove', '93639996', 'https://www.rightmove.co.uk/properties/93639996', 1150000, 'offers_over', 4, 3, 'detached', 'Old Barn Close, Emmer Green, Reading', 'RG4 8QY', 51.484804, -0.973554, 'freehold', NULL, NULL, NULL, 'G', NULL, NULL, NULL, '["Four bedroomed detached house", "Immaculate decorative order throughout", "Large living/dining area", "Kitchen with separate utility room", "Vast garden", "Parquet flooring throughout living areas", "Quiet cul de sac", "Onward chain is closed!"]', 'Bridges are delighted to bring to the market this four bedroomed, detached house situated in a generous corner plot in a quiet cul de sac in the heart of Emmer Green. Set behind electric gates the front drive is paved and provides parking for multiple cars. Accessed via an enclosed porch the house benefits from parquet flooring running throughout the downstairs living areas and is flooded with light due to glass panelled doors and partitions. Presented in immaculate decorative order throughout the property has a vast living/dining area which leads to an orangery with underfloor heating, two sets of French Doors, to garden, and a vast, domed roof lantern. The kitchen benefits from a range of floor and eye level units and has space for a table. There is a separate utility/laundry room, study, with fitted furniture and cloakroom. Upstairs are four double bedrooms, the main with a wall of built in wardrobes. There are two family bathrooms one with bath and hand shower and the other with separate shower and jacuzzi style bath. The garden is large with a patio area, established planting and generous lawn. There is a double garage with electric door and two brick storage areas. The onward chain is closed and an early viewing recommended by the vendors` sole agent!
