INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-94269678', 'rightmove', '94269678', 'https://www.rightmove.co.uk/properties/94269678', 1175000, 'offers_over', 5, 2, 'end_of_terrace', 'Highview Road, Ealing, W13', 'W13 0HN', 51.519024, -0.325119, 'freehold', NULL, NULL, NULL, 'F', NULL, NULL, 'first', '["Elegant Period Family Home", "Two Reception Rooms", "WC/Cloakroom", "Utility Room", "Five Bedrooms", "Two Bathrooms", "Split Level Garden/Studio Office", "Half Mile To Elizabeth Line"]', 'A superb end-of-terrace family home which has been recently enhanced and updated by the current owners to an excellent standard, whilst retaining much of its early 20th-century character and charm. The ground floor features a comfortable front reception room leading through to a spacious open-plan kitchen and dining area. The recently updated kitchen offers ample fitted cabinetry and integrated appliances, with matching units continuing into the adjoining utility area. A convenient guest WC completes the ground floor. On the first floor are two generous double bedrooms, a single bedroom, currently arranged as a dressing room, and a family bathroom. The top floor offers two further bedrooms, including a well-proportioned double and a good-sized single, together with a separate bathroom, providing flexible accommodation for a growing family.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-94271754', 'rapidapi_uk_real_estate_rightmove', '94271754', 'https://www.rightmove.co.uk/properties/94271754', 900000, 'guide_price', 3, 2, 'detached', 'Merrow Chase, Merrow, GU1', 'GU1 2RZ', 51.240673, -0.533007, 'freehold', NULL, NULL, NULL, 'F', NULL, NULL, NULL, '["Detached three bedroom family home", "Open views across the golf course", "Excellent opportunity to update and modernise", "Potential to extend, subject to planning permission", "Sitting room with direct access to the rear garden", "Separate dining room & fitted kitchen", "First floor bathroom & downstairs shower room", "Generous rear garden, driveway parking and garage", "Lovely walks accessible through the garden gate", "Within the catchment area of several well-regarded schools"]', '“The setting is the great attraction here. Having Guildford Golf Club immediately beyond the rear garden gives the house an outlook that is difficult to replicate, particularly in such an established residential area. The well-presented house offers a practical layout, with separate living and dining rooms, three bedrooms and a good-sized garden. There is scope to modernise, but the more interesting opportunity is to consider how the accommodation could be reworked or extended, subject to planning, to take greater advantage of the garden and views." Anthony Brown - Chantries & Pewleys
