INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-94580601', 'rightmove', '94580601', 'https://www.rightmove.co.uk/properties/94580601', 800000, NULL, 3, 2, 'semi_detached', 'Billington Road, New Cross', 'SE14 5QH', 51.47615, -0.046819, 'freehold', NULL, NULL, NULL, 'D', NULL, NULL, NULL, '["Semi-detached home", "Three bedrooms", "Victorian architecture style", "Driveway parking", "Large rear garden", "Energy rating: c"]', 'A beautifully presented three-bedroom house combining Victorian-inspired kerb appeal with stylish, contemporary living. The property offers well-designed interiors, three bedrooms and two newly fitted bathrooms, with the main bathroom fitted with attractive terrazzo tiling. The accommodation provides versatile living space throughout, ideal for modern family life. Externally, a private driveway offers convenient off-street parking, while the impressive 70ft plus rear garden provides generous space for outdoor entertaining, dining and relaxation, making this an appealing home both inside and out.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-94583757', 'rightmove', '94583757', 'https://www.rightmove.co.uk/properties/94583757', 685000, NULL, 4, 2, 'terraced', 'Charles Road, Ealing', 'W13 0ND', 51.520291, -0.323732, 'freehold', NULL, NULL, NULL, 'E', 'C', NULL, NULL, '["Four Double Bedroom Townhouse", "Two Bathrooms", "Off Street Parking on Front Drive", "16ft Reception Room", "Kitchen/Dining Room", "Ground Floor wc", "Easy Access for Elizabeth Line Stations", "No Onward Chain", "Private Rear Garden", "EPC Rating C. Council Tax Band E"]', 'Offering versatile accommodation arranged over three floors, this four-bedroom, two-bathroom townhouse has off-street parking and presents an excellent opportunity for buyers seeking a spacious home with plenty of potential. The property would benefit from some updating, allowing the next owner the opportunity to personalise the accommodation to their own taste and style. There is also scope to extend to the rear, subject to the necessary planning permissions, as demonstrated by neighbouring properties. Being marketed by the vendors’ sole agent, we confirm the property is offered for sale with no onward chain, helping to facilitate a more straightforward purchase. Further benefits include an impressive EPC rating of C, offering encouraging energy efficiency for a property of this type. An excellent opportunity for buyers looking for a well-proportioned home with scope to improve and extend.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-94588449', 'rightmove', '94588449', 'https://www.rightmove.co.uk/properties/94588449', 675000, NULL, 3, 1, 'terraced', 'Admiral Street, London SE8', 'SE8 4HY', 51.472031, -0.023181, 'freehold', NULL, 0, 0, 'D', NULL, NULL, NULL, '["In need of modernisation", "St Johns Conservation Area", "3 bedrooms", "Cul de sac", "Great schools, bars & shops locally", "Potential to extend (STPP)", "Excellent transport links", "Chain Free"]', 'A home with heart in the heart of St John & bursting with potential.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-94592364', 'rightmove', '94592364', 'https://www.rightmove.co.uk/properties/94592364', 450000, 'fixed_price', 2, 1, 'flat', 'Harriet Court, 29 Pomeroy Street, London, SE14', 'SE14 5BW', 51.476239, -0.052438, 'leasehold', 115, 1625.76, 250, 'C', NULL, NULL, 'first', '["First Floor (building has a lift)", "Approx. 809 Sqft Gross Internal Area", "Spacious, Open-Plan Kitchen/Reception", "Two Good-Sized Double Bedrooms", "Stylish Bathroom", "Very Good Energy Efficiency Rating", "Large Balcony", "Short Walk to Queens Road Peckham Station"]', 'A spacious apartment on the first floor of this modern development. The property has a twenty-five foot reception room with open-plan kitchen area featuring sleek, white units and integrated appliances. There is a main bedroom with fitted wardrobe plus a very similar-sized second double bedroom, a stylish bathroom and a large hallway storage cupboard. A large balcony can be accessed from either the living room or the main bedroom. Harriet Court was built with well insulated walls and floor, high performance glazing and gas central heating systems resulting in a very good energy-efficiency rating. Queens Road Peckham Station, for London Overground trains plus Southern services between East Croydon/Beckenham Junction and London Bridge, is just a short walk away.
