INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-94613979', 'rightmove', '94613979', 'https://www.rightmove.co.uk/properties/94613979', 600000, 'guide_price', 4, 1, 'detached', 'Lakeside Place, London Colney, St. Albans, Hertfordshire, AL2', 'AL2 1PZ', 51.718246, -0.294847, 'freehold', NULL, NULL, NULL, 'E', NULL, NULL, NULL, '["Recently refurbished throughout with contemporary finishes", "Converted garage providing additional reception space", "Chain free sale", "Four bedrooms & two reception rooms", "Modern fitted kitchen with garden access", "Rear garden with lawn & patio", "Off-street parking to the front", "Ground floor WC & family bathroom"]', 'This recently refurbished four-bedroom detached house in London Colney combines a peaceful setting opposite the river with excellent access to the M1 & M25. The former garage has been converted into an additional reception room, giving the property two separate living spaces alongside a dedicated dining room. With contemporary finishes throughout, a neatly maintained rear garden and off-street parking, it''s a home that balances modern family living with the pleasure of having riverside walks close by.
