INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-94649835', 'rightmove', '94649835', 'https://www.rightmove.co.uk/properties/94649835', 400000, 'offers_over', 2, 1, 'flat', 'Arcola Street, Hackney', 'E8 2DY', 51.551925, -0.073128, 'leasehold', 88, 160, 20, 'B', NULL, NULL, 'top', '["Two Bedroom Flat", "Positioned On The Top Floor", "Two Generous Sized Bedrooms", "Great Storage", "Conveniently Located Between Dalston and Stoke Newington", "Secure Building"]', 'Set between the lively streets of Dalston and the independent shops and cafés of Stoke Newington, this bright two bedroom top floor flat offers generous living space, two well-sized bedrooms and plenty of storage. With some of East London''s favourite restaurants, green spaces and neighbourhood hangouts on your doorstep, there''s plenty to enjoy in this well-connected corner of Hackney.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-94649940', 'rightmove', '94649940', 'https://www.rightmove.co.uk/properties/94649940', 600000, NULL, 2, 2, 'flat', 'Ashwin Street, E8', 'E8 3DL', 51.54713, -0.075302, 'leasehold', 116, 4000, 250, 'D', NULL, NULL, NULL, '["Leasehold apartment with private balcony", "Two bedrooms and two bathrooms", "Master bedroom occupies an en-suite bathroom", "Open plan reception/kitchen/diner", "Well positioned for Kingsland Road and its cafés, pubs and restaurants", "Within catchment of highly regarded schools", "Dalston Kingsland & Dalston Junction Overground stations"]', 'Situated in the heart of Dalston, this beautifully positioned two-bedroom apartment offers contemporary living in one of East London’s most vibrant and sought-after neighbourhoods. Ideally located, an eclectic mix of independent cafés, acclaimed restaurants, boutique shops, and cultural hotspots surround the property. Stepping inside, the property offers a comfortable living space with a modern layout. The generous reception/kitchen/diner provides the perfect setting for relaxing and entertaining, with access to a private balcony offering desirable morning and afternoon sunlight. The property features two spacious and bright bedrooms, with the larger bedroom benefitting from its own en-suite bathroom, complemented by a second modern bathroom, offering added convenience for residents and guests alike. Travelling to the City and beyond is made easy with Dalston Kingsland and Dalston Junction Overground stations, as well as numerous bus links, placed right on its doorstep. Available to the market chain-free.', 'BlakeStanley Estate Agents, Hackney', '2026-10-23T11:42:11Z', '2026-10-23T22:58:50Z', '[]');
