INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields) VALUES ('rm-94670358', 'rightmove', '94670358', 'https://www.rightmove.co.uk/properties/94670358', 425000, NULL, 3, 1, 'end_of_terrace', 'Sussex Road, Watford, WD24', 'WD24 5HL', 51.672005, -0.404938, 'freehold', NULL, NULL, NULL, 'C', NULL, NULL, NULL, '["CHAIN FREE", "THREE BEDROOMS OFF LANDING", "END OF TERRACE HOUSE", "HUGE POTENTIAL TO IMPROVE AND EXTEND (STPP)", "REQUIRES MODERNISATION THROUGHOUT", "SPACIOUS THROUGH LOUNGE"]', 'Offered on a chain free basis and situated on a sought after residential road is this larger than average three bedroom end of terrace house offering huge potential and requiring modernisation throughout. The property offers spacious accommodation comprising an entrance hallway, generous through lounge, good size kitchen, inner lobby/utility and large shower room to the ground floor, whilst upstairs are three bedrooms, all accessed independently from the landing. Externally, the property benefits from a large rear garden with a summer house and workshop, offering excellent scope for landscaping and further improvement. Whilst requiring updating throughout, the property presents a fantastic opportunity for purchasers looking to create a home to their own taste and specification, with excellent potential to extend, subject to the usual planning consents. This property is ideally situated on Sussex Road, known for its attractive residential setting and convenient access to local shops, schools and transport links, including Watford Junction Station. Watford Town Centre is also within easy reach, whilst the nearby M1, M25 and A41 provide excellent road connections.
